function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100) return 'nums needs 2 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each value is an integer from -1000 to 1000.';
  if (!Number.isInteger(k) || k < 1 || 2 * k > nums.length) return 'k must be at least 1, with 2 * k <= nums.length.';
  return null;
}

