function hasIncreasingSubarrays(nums, k) {
  const n = nums.length;
  // ending[i]: length of the longest strictly increasing subarray that ends at index i.
  const ending = new Array(n).fill(1);
  for (let i = 1; i < n; i++) {
    if (nums[i] > nums[i - 1]) {
      ending[i] = ending[i - 1] + 1;
    }
  }
  for (let end = 2 * k - 1; end < n; end++) {
    if (ending[end] >= k && ending[end - k] >= k) {
      return true;
    }
  }
  return false;
}

