function hasIncreasingSubarrays(nums, k) {
  // Check every pair of back-to-back blocks element by element.
  const increasing = start => {
    for (let i = start + 1; i < start + k; i++) if (nums[i] <= nums[i - 1]) return false;
    return true;
  };
  for (let a = 0; a + 2 * k <= nums.length; a++) {
    if (increasing(a) && increasing(a + k)) return true;
  }
  return false;
}

