function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 100 : 2 + Math.floor(rand() * 11);
  // Large inputs favour small k so that both answers appear.
  const k = 1 + Math.floor((large ? rand() * rand() : rand()) * Math.floor(n / 2));
  const span = large ? 1000 : 6;
  const nums = [];
  let value = 0;
  for (let i = 0; i < n; i++) {
    const r = rand();
    // Climb most of the time, sometimes repeat a value, sometimes jump anywhere: runs of varied length.
    if (i === 0 || r >= 0.85 || value + 3 > span) value = Math.floor(rand() * (2 * span + 1)) - span;
    else if (r < 0.7) value += 1 + Math.floor(rand() * 3);
    nums.push(value);
  }
  return [nums, k];
}
